SELECT id, customer_id, store_id, order_date, status, LEAD(shipping_fee, 1) OVER (PARTITION BY status ORDER BY order_date ASC, id ASC) AS next_shipping_fee, AVG(discount) OVER (PARTITION BY customer_id ORDER BY amount ASC, id ASC ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING) AS discount_avg_3_prior, LAG(shipping_fee, 1) OVER (PARTITION BY channel ORDER BY order_date ASC, id ASC) AS prev_shipping_fee FROM orders;
